CREATE SCHEMA IF NOT EXISTS YASP_DEMO.ANALYTICS;
CREATE TABLE IF NOT EXISTS YASP_DEMO.PUBLIC.USERS (ID NUMBER(18,0) PRIMARY KEY, FULL_NAME VARCHAR(100) NOT NULL, EMAIL VARCHAR(200) UNIQUE, CREATED_AT TIMESTAMP_NTZ(6));
COMMENT ON TABLE YASP_DEMO.PUBLIC.USERS IS 'Demo customers';
ALTER TABLE YASP_DEMO.PUBLIC.USERS ALTER COLUMN ID COMMENT 'Customer identifier';
INSERT INTO YASP_DEMO.PUBLIC.USERS SELECT * FROM VALUES (1, 'Ada Lovelace', 'ada@example.test', '2026-01-01 12:00:00'), (2, 'Grace Hopper', NULL, '2026-01-02 12:00:00'), (3, 'Alan Turing', 'alan@example.test', '2026-01-03 12:00:00') v WHERE NOT EXISTS (SELECT 1 FROM YASP_DEMO.PUBLIC.USERS);
CREATE TABLE IF NOT EXISTS YASP_DEMO.PUBLIC.PRODUCTS (ID NUMBER(18,0) PRIMARY KEY, NAME VARCHAR(100), PRICE NUMBER(18,2));
INSERT INTO YASP_DEMO.PUBLIC.PRODUCTS SELECT * FROM VALUES (1, 'Notebook', 12.50), (2, 'Keyboard', 80.00) v WHERE NOT EXISTS (SELECT 1 FROM YASP_DEMO.PUBLIC.PRODUCTS);
CREATE TABLE IF NOT EXISTS YASP_DEMO.PUBLIC.ORDERS (ID NUMBER(18,0) PRIMARY KEY, USER_ID NUMBER(18,0) REFERENCES USERS(ID), PRODUCT_ID NUMBER(18,0) REFERENCES PRODUCTS(ID), AMOUNT NUMBER(30,9) DEFAULT 0, ORDERED_AT TIMESTAMP_NTZ(6));
INSERT INTO YASP_DEMO.PUBLIC.ORDERS SELECT * FROM VALUES (1, 1, 1, 12.500000001, '2026-01-05 10:00:00'), (2, 2, 2, 80.000000002, '2026-01-06 11:00:00') v WHERE NOT EXISTS (SELECT 1 FROM YASP_DEMO.PUBLIC.ORDERS);
CREATE TABLE IF NOT EXISTS YASP_DEMO.PUBLIC.SUPPORT_TICKETS (ID NUMBER(18,0) PRIMARY KEY, USER_ID NUMBER(18,0) REFERENCES USERS(ID), SUBJECT VARCHAR(200));
INSERT INTO YASP_DEMO.PUBLIC.SUPPORT_TICKETS SELECT * FROM VALUES (1, 1, 'Delivery question'), (2, 3, 'Product question') v WHERE NOT EXISTS (SELECT 1 FROM YASP_DEMO.PUBLIC.SUPPORT_TICKETS);
CREATE OR REPLACE VIEW YASP_DEMO.ANALYTICS.DAILY_SALES AS SELECT CAST(ORDERED_AT AS DATE) AS DAY, SUM(AMOUNT) AS REVENUE FROM YASP_DEMO.PUBLIC.ORDERS GROUP BY CAST(ORDERED_AT AS DATE);
CREATE TABLE IF NOT EXISTS YASP_DEMO.ANALYTICS.METADATA_TYPES (TENANT_ID NUMBER(18,0), ID NUMBER(18,0), AMOUNT NUMBER(38,9) NOT NULL, "MixedCase" VARCHAR(30), PAYLOAD BINARY, CREATED TIMESTAMP_NTZ(6), PRIMARY KEY (TENANT_ID, ID));
INSERT INTO YASP_DEMO.ANALYTICS.METADATA_TYPES SELECT 1, 1, 12345678901234567890.123456789, NULL, TO_BINARY('00ff', 'HEX'), '2026-01-01 12:34:56.123456' WHERE NOT EXISTS (SELECT 1 FROM YASP_DEMO.ANALYTICS.METADATA_TYPES);
USE SCHEMA YASP_DEMO.ANALYTICS;
CREATE TABLE IF NOT EXISTS YASP_DEMO.ANALYTICS.TYPE_REFERENCES (TENANT_ID NUMBER(18,0), TYPE_ID NUMBER(18,0), FOREIGN KEY (TENANT_ID, TYPE_ID) REFERENCES METADATA_TYPES(TENANT_ID, ID));

USE SCHEMA YASP_DEMO.PUBLIC;
